use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-worker-attribution176";const P:&str="/home/ubuntu/src/zopro-perf-work/g2-queue-index-composition176";
fn r(s:&str)->PathBuf{Path::new(R).join(s)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn sha(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn near(a:f64,b:f64){assert!((a-b).abs()<1e-11*a.abs().max(b.abs()).max(1.));}
fn main(){assert!(!r("review.json").exists());let a=load(r("analysis.json"));let callers=load(Path::new(P).join("callers.json"));let pins=load(r("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(sha(p),h.as_str().unwrap());}let plan=load(r("plan.json"));for s in plan["steps"].as_array().unwrap(){let b=r("check").join(s["name"].as_str().unwrap());let e=load(b.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for f in["stdout","stderr"]{assert_eq!(sha(b.join(format!("{f}.log"))),e[format!("{f}_sha256")]);}let c=load(b.join("command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],s["argv"].as_array().unwrap());assert_eq!(c["environment"],json!({}));}
 let mut grand=0;let mut epoch_total=0;for profile in a["profiles"].as_array().unwrap(){let name=profile["profile"].as_str().unwrap();let call=&callers[name];let pid=call["pid"].as_u64().unwrap();let mut known=BTreeMap::new();known.insert(pid,None);for w in call["worker_rows"].as_array().unwrap(){known.insert(w["tid"].as_u64().unwrap(),Some(w["cpu"].as_u64().unwrap()));}let mut counts=BTreeMap::<u64,[u64;3]>::new();for tid in known.keys(){counts.insert(*tid,[0;3]);}
 let raw=Path::new(P).join(format!("perf/{name}.data"));assert_eq!(sha(raw),profile["raw_sha256"]);let decode=Path::new(P).join(format!("runs/decode-{name}/stdout.log"));assert_eq!(sha(&decode),profile["decode_sha256"]);for line in fs::read_to_string(decode).unwrap().lines().filter(|l|!l.starts_with('#')&&!l.trim().is_empty()){let f=line.split_whitespace().collect::<Vec<_>>();let mut ids=f[0].split('/');assert_eq!(ids.next().unwrap().parse::<u64>().unwrap(),pid);let tid=ids.next().unwrap().parse::<u64>().unwrap();assert!(ids.next().is_none());let cpu=f[1].trim_matches(['[',']']).parse::<u64>().unwrap();assert!(cpu<32);if let Some(expected)=known[&tid]{assert_eq!(cpu,expected);}assert_eq!(f[3],"16000000");let sym=f[5];let epoch=sym.contains("15crossbeam_epoch7default11with_handle")&&sym.contains("3pin");let apply=sym.contains("11g2_borrowed5apply");let count=counts.get_mut(&tid).unwrap();count[0]+=1;count[1]+=u64::from(epoch);count[2]+=u64::from(apply);}
 let rows=profile["workers"].as_array().unwrap().iter().chain(std::iter::once(&profile["caller"]));for row in rows{let n=counts[&row["tid"].as_u64().unwrap()];assert_eq!(n[0],row["samples"]);assert_eq!(n[1],row["counts"]["epoch_pin"].as_u64().unwrap_or(0));assert_eq!(n[2],row["counts"]["borrowed_apply"].as_u64().unwrap_or(0));assert_eq!(n[0],row["counts"].as_object().unwrap().values().map(|v|v.as_u64().unwrap()).sum::<u64>());}
 let total=counts.values().map(|n|n[0]).sum::<u64>();assert_eq!(total,profile["samples"]);let epoch=counts.values().map(|n|n[1]).sum::<u64>();assert_eq!(epoch,profile["category_totals"]["epoch_pin"]);assert_eq!(counts[&pid][1],0);assert_eq!(counts[&pid][2],0);let apply=counts.iter().filter(|(tid,_)|**tid!=pid).map(|(_,n)|n[2]).collect::<Vec<_>>();assert_eq!(apply.len(),32);let mean=apply.iter().sum::<u64>()as f64/32.;let variance=apply.iter().map(|&n|(n*n)as f64).sum::<f64>()/32.-mean*mean;let stat=&profile["borrowed_apply_distribution"];near(stat["mean"].as_f64().unwrap(),mean);near(stat["coefficient_of_variation"].as_f64().unwrap(),variance.sqrt()/mean);assert_eq!(stat["minimum"],*apply.iter().min().unwrap());assert_eq!(stat["maximum"],*apply.iter().max().unwrap());assert_eq!(stat["workers_with_samples"],apply.iter().filter(|&&n|n>0).count());grand+=total;epoch_total+=epoch;}
 assert_eq!(grand,77807);assert_eq!(a["source_profile_samples"],grand);let result=json!({"passed":true,"source_pin_entries":pins.as_object().unwrap().len(),"successful_workflow_commands":2,"actual_argv_environment_exits_and_stream_hashes_checked":true,"raw_samples_reparsed":grand,"raw_epoch_pin_samples_reparsed":epoch_total,"classification_uses_raw_mangled_tokens_without_analyzer_or_demangler":true,"all_epoch_pin_samples_on_registered_workers":true,"borrowed_apply_on_all32_workers_in_every_profile":true,"all_per_thread_totals_CPU_and_distribution_statistics_checked":true,"new_recordings":0,"new_queries":0,"new_proofs":0,"adopted":false,"goal_achieved":false});fs::write(r("review.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
